{"hypotheses": [
  {
    "name": "Supply Chain Antifragility Blend",
    "mechanism": "Firms with both strong customer momentum and unexpectedly high R&D investment may benefit uniquely from supply chain disruptions, as innovation and responsive end-market demand interact to create positive return convexity to shocks. The composite captures this antifragility, which neither input fully isolates alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": 0.5, "primitive": "SurpriseRD"},
        {"weight": -0.5, "primitive": "InventoryGrowth"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Ownership-Dispersion Contrarian",
    "mechanism": "Low institutional ownership coupled with high forecast dispersion indicates neglected and controversial stocks, which historically revert as uncertainty resolves and institutions reallocate. The composite exploits mean-reversion from this neglected-controversy interaction, separate from each input’s average effect.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "DelBreadth"},
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": 0.5, "primitive": "STreversal"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "correlation", "primitive": "DelBreadth", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Franchise Intangibles Premium",
    "mechanism": "Combining brand investment and organizational capital proxies with low equity issuance captures firms building intangible moats without diluting shareholders. The composite isolates long-term value from franchise development, distinct from each input alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BrandInvest"},
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": -0.5, "primitive": "NetEquityFinance"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "BrandInvest", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Crisis-Driven Credit Quality Growth",
    "mechanism": "Firms with recent credit rating downgrades that also exhibit high sales growth over inventory growth can outperform in low-rate regimes, as forced efficiency gains and operational resilience are rewarded by markets hunting for growth during credit stress.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "CredRatDG"},
        {"weight": 1.0, "primitive": "GrSaleToGrInv"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Liquidity Timing Innovation",
    "mechanism": "Firms with positive liquidity betas and high unexpected R&D get underpriced during high market volatility, as markets overreact to perceived risk. Their innovative activities, however, enable rapid liquidity adjustment and recovery, producing an alpha not captured by either signal alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BetaLiquidityPS"},
        {"weight": 0.5, "primitive": "SurpriseRD"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "BetaLiquidityPS", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Post-IPO Underwriting Reluctance",
    "mechanism": "Firms with recent IPOs and low net debt financing experience constrained post-IPO funding, fostering capital discipline and reducing agency costs. This blend exploits a behavioral supply-demand imbalance not directly targeted by standard IPO or leverage signals.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AgeIPO"},
        {"weight": -1.0, "primitive": "NetDebtFinance"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "NetDebtFinance", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 21
  },
  {
    "name": "Forecast Error Volatility Defensive",
    "mechanism": "Stocks with high variance in forecast errors and steady dividend payments behave defensively in down markets, as their payouts anchor investor sentiment while forecast uncertainty offers upside optionality. The composite self-hedges against macro shocks more effectively than its parts.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "VarCF"},
        {"weight": 0.5, "primitive": "DivYieldST"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.72,
    "expected_decay_half_life_months": 27
  },
  {
    "name": "Surprise Tax Shield Momentum",
    "mechanism": "Combining positive momentum in operating cash flows with unexpected increases in tax payments identifies firms whose earnings quality is underappreciated, as tax shocks signal persistent real profitability. The interaction outperforms either tax or cash flow momentum alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "cfp"},
        {"weight": 0.5, "primitive": "ChTax"},
        {"weight": 1.0, "primitive": "Mom12mOffSeason"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "subperiod_consistency"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "correlation", "primitive": "Mom12mOffSeason", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.68,
    "expected_decay_half_life_months": 34
  }
]}
